/* ====================== NEGOCIO_MARK */
/* ====================== NEGÓCIO: planos, lojas, alertas, recursos novos ====================== */
let LOJAS=[],PLANO=normPlano(null),ASSIN=null,USO_IA=0,PERFIL=null,EMP_ID=null,ALERTAS=[],PLANOS=[],EXTRAS=[],PACOTES=[],CONTA_CONC=[];
const vagasExtra=()=>EXTRAS.reduce((a,x)=>a+(x.quantidade||0),0);
function extrasUsadas(){const n={};CONTA_CONC.forEach(x=>{n[x.empresa_id]=(n[x.empresa_id]||0)+1});return Object.values(n).reduce((a,q)=>a+Math.max(0,q-PLANO.max_concorrentes),0)}
const podeAdd=()=>conc.length<PLANO.max_concorrentes||extrasUsadas()<vagasExtra();
const pausadas=()=>conc.filter(c=>c.pausada);
const brl=v=>'R$ '+Number(v).toFixed(2).replace('.',',');
function cardPacote(k,i){return '<div class="card pacote'+(k.destaque?' dest':'')+'">'+(k.destaque?'<span class="chip ig" style="align-self:flex-start">'+esc(k.destaque)+'</span>':'')+'<b style="font-size:18px">'+esc(k.nome)+'</b><div><b class="preco">'+brl(k.preco)+'</b><span class="sm">/mês</span></div><span class="sm">'+(k.quantidade>1?brl(k.preco/k.quantidade)+' por concorrente':'Uma vaga a mais')+' · vale para todas as suas lojas</span><button class="btn '+(k.destaque&&i<2?'pri':'sec')+'" data-extra="'+k.id+'">Comprar</button></div>'}
function ofertaExtras(){const lim=PLANO.max_concorrentes,ks=PACOTES.slice(0,2);
 openModal('<h2 id="mT" style="font-size:21px;font-weight:900">Suas vagas acabaram</h2><p class="mut">O plano '+esc(PLANO.nome)+' inclui '+lim+' concorrente'+(lim>1?'s':'')+' por loja'+(vagasExtra()?' e você já usa '+vagasExtra()+' vaga'+(vagasExtra()>1?'s':'')+' extra'+(vagasExtra()>1?'s':''):'')+'. Compre mais vagas sem trocar de plano:</p>'+(ks.length?'<div class="pacotes">'+ks.map(cardPacote).join('')+'</div>':'')+'<div class="row"><button class="btn sec fl" data-act="close">Agora não</button><a class="btn sec fl" href="#planos" data-act="close" data-gopacotes="1">Ver todos os pacotes</a></div>')}
function normPlano(d){const p=Array.isArray(d)?d[0]:d;return p&&p.id?p:{id:'gratis',nome:'Grátis',preco:0,max_lojas:1,max_concorrentes:1,max_termos:0,intervalo_horas:24,ia_mes:5,recursos:['graficos','hashtags','gerador','perfil']}}
const temR=r=>!CLOUD||((PLANO.recursos||[]).includes(r));
const SEGS={'Moda e acessórios':['Moda feminina','Moda masculina','Moda infantil','Moda plus size','Moda fitness e praia','Moda íntima','Calçados','Bolsas e acessórios','Joias e semijoias','Óticas','Brechó e multimarcas'],'Beleza e saúde':['Cosméticos e perfumaria','Salão de beleza e estética','Barbearia','Farmácia e drogaria','Suplementos','Produtos naturais','Clínica e consultório'],'Alimentação':['Restaurante','Lanchonete e hamburgueria','Pizzaria','Cafeteria e padaria','Doceria e confeitaria','Açaí e sorveteria','Mercado e mercearia','Hortifrúti','Açougue e frios','Bebidas e adega','Marmitas e delivery'],'Casa e construção':['Móveis','Decoração','Cama, mesa e banho','Utilidades domésticas','Material de construção','Iluminação e elétrica','Jardinagem e flores'],'Tecnologia':['Celulares e acessórios','Informática','Eletrônicos e eletrodomésticos','Games','Assistência técnica'],'Pets':['Pet shop','Clínica veterinária','Banho e tosa'],'Infantil':['Brinquedos','Artigos para bebê','Festas e eventos infantis'],'Esporte e lazer':['Artigos esportivos','Academia e estúdio','Bicicletas','Camping e pesca','Instrumentos musicais'],'Automotivo':['Autopeças','Oficina mecânica','Estética automotiva','Motos e peças'],'Presentes e papelaria':['Papelaria','Livraria','Presentes e artesanato','Floricultura','Gráfica e personalizados'],'Serviços':['Cursos e educação','Fotografia e eventos','Turismo e viagens','Imobiliária','Serviços gerais']};
const NOME_RECURSO={calendario:'Calendário da semana',inspiracoes:'Inspirações',campanhas:'Campanhas de datas',pdf:'Relatório em PDF',alertas:'Alertas por e-mail',relatorio_mensal:'Relatório mensal automático',indice:'Índice do nicho',marca_branca:'Relatório com a sua marca',aprovacao:'Aprovação de posts pelo cliente',avaliacoes:'Avaliações do Google',whatsapp:'Alertas no WhatsApp',perfil:'Raio-X do seu perfil',gerador:'Criar com IA',hashtags:'Ranking de hashtags',graficos:'Gráficos de evolução'};
function planoCom(r){const ps=(PLANOS.length?PLANOS:[]).filter(p=>(p.recursos||[]).includes(r)).sort((a,b)=>a.ordem-b.ordem);return ps[0]?ps[0].nome:'pago'}
function trava(r,extra){return '<div class="card empty trava"><span class="ring"><span style="width:64px;height:64px;color:#962fbf">'+ic('shield',28)+'</span></span><h2 style="font-size:20px">'+esc(NOME_RECURSO[r]||'Recurso')+'</h2><p class="mut" style="max-width:44ch">'+(extra||'')+' Disponível a partir do plano <b>'+esc(planoCom(r))+'</b>.</p><a class="btn pri" href="#planos">Ver planos</a></div>'}
function upsell(msg){openModal('<h2 id="mT" style="font-size:21px;font-weight:900">Hora de crescer 🚀</h2><p class="mut">'+esc(msg)+'</p><div class="row"><button class="btn sec fl" data-act="close">Agora não</button><a class="btn pri fl" href="#planos" data-act="close">Ver planos</a></div>')}
async function carregaPlanos(){if(PLANOS.length||!CLOUD)return;const r=await sb.from('planos').select('*').eq('ativo',true).order('ordem');PLANOS=(r&&r.data)||[]}

/* ---------- várias lojas ---------- */
function barraLoja(){if(!LOJAS.length)return '';if(PLANO.max_lojas<=1&&LOJAS.length<=1)return '';
 return '<div class="lojabar"><label class="row" style="gap:8px;flex:1;min-width:0"><span class="sm" style="font-weight:800">Loja:</span><select id="selLoja" aria-label="Trocar de loja">'+LOJAS.map(l=>'<option value="'+l.id+'"'+(l.id===EMP_ID?' selected':'')+'>'+esc(l.nome_fantasia)+(l.principal?' (sua)':'')+'</option>').join('')+'</select></label><span class="sm">'+LOJAS.length+'/'+PLANO.max_lojas+'</span><button class="btn sec sm" data-neg="novaloja">'+ic('plus',14)+'Nova loja</button></div>'}
async function trocarLoja(id){try{localStorage.setItem('radar_loja',id)}catch(_){}$('root').innerHTML='<div style="min-height:100vh;display:grid;place-items:center"><span class="spin" style="width:32px;height:32px"></span></div>';rel.hist=null;histC={};await carregar();route()}
function formLoja(){const opts=Object.entries(SEGS).map(([g,l])=>'<optgroup label="'+g+'">'+l.map(o=>'<option>'+o+'</option>').join('')+'</optgroup>').join('')+'<optgroup label="Outro"><option value="Outro">Outro</option></optgroup>';
 return '<h2 id="mT" style="font-size:21px;font-weight:900">Nova loja / cliente</h2><p class="sm">Cada loja tem as próprias concorrentes, calendário e relatórios.</p><form id="fLoja" style="display:grid;gap:10px">'+F('nlNome','Nome da loja','text','Ex.: Pizzaria Forno Leste',1)+'<label class="f" for="nlSeg"><span>Nicho <em>*</em></span><select id="nlSeg" required><option value="">Selecione</option>'+opts+'</select></label>'+F('nlOutro','Qual nicho? (se escolheu Outro)','text','',0)+'<div class="modos" role="radiogroup">'+[['fisica','🏪','Física'],['online','🛒','Online'],['ambas','🔁','As duas']].map((m,i)=>'<label class="modo"><input type="radio" name="nlModo" value="'+m[0]+'"'+(i===0?' checked':'')+'><span>'+m[1]+'</span><b>'+m[2]+'</b></label>').join('')+'</div>'+F('nlCidade','Cidade','text','Ex.: São Paulo / SP',0)+F('nlIg','Instagram da loja','text','@loja',1,'autocapitalize="none"')+F('nlSite','Site (opcional)','text','loja.com.br',0,'autocapitalize="none"')+'<label class="f" for="nlDesc"><span>O que a loja vende</span><textarea id="nlDesc" rows="2" placeholder="Ex.: pizzas artesanais com entrega na Zona Leste"></textarea></label>'+F('nlCli','E-mail do cliente (recebe o relatório mensal)','email','cliente@email.com',0,'autocapitalize="none"')+'<div class="row"><button type="button" class="btn sec fl" data-act="close">Cancelar</button><button class="btn pri fl" id="nlOk">Criar loja</button></div></form>'}
async function salvarLoja(e){e.preventDefault();const nome=$('nlNome').value.trim();let seg=$('nlSeg').value;if(seg==='Outro')seg=$('nlOutro').value.trim();let ig=$('nlIg').value.trim().replace(/.*instagram\.com\//i,'').replace(/[/?#].*$/,'');
 if(nome.length<2||!seg||!ig){toast('Preencha nome, nicho e Instagram.');return}ig=ig[0]==='@'?ig:'@'+ig;$('nlOk').disabled=true;
 const q=await sb.from('empresas').insert({nome_fantasia:nome,segmento:seg,modalidade:(document.querySelector('input[name=nlModo]:checked')||{}).value||null,cidade:$('nlCidade').value.trim()||null,instagram:ig,site:$('nlSite').value.trim()||null,descricao:$('nlDesc').value.trim()||null,cliente_email:$('nlCli').value.trim()||null}).select().single();
 if(q.error){$('nlOk').disabled=false;toast(traduz(q.error.message));return}closeModal();toast('Loja criada!');trocarLoja(q.data.id)}

/* ---------- planos e assinatura ---------- */
function usoBar(rot,a,b){const pc=b?Math.min(100,Math.round(a/b*100)):0;return '<div><div class="row"><span class="sm fl" style="color:var(--ink)">'+rot+'</span><b class="sm">'+a+' / '+b+'</b></div><div class="bar"><i data-w="'+pc+'" style="background:'+(pc>=90?'#dc2626':'var(--ig2)')+'"></i></div></div>'}
function renderPlanos(){if(!CLOUD)return so('Os planos valem para a versão conectada.');if(!PLANOS.length){carregaPlanos().then(()=>{if(location.hash==='#planos')route()});return carregando('Carregando planos…')}
 const pago=ASSIN&&ASSIN.mp_preapproval_id&&PLANO.id!=='gratis';
 let h='<div class="ph"><div><span class="lbl">Planos</span><h1>Escolha como o Radar trabalha para você</h1></div></div>'+
 '<div class="card" style="display:grid;gap:12px;margin-bottom:16px"><div class="row" style="flex-wrap:wrap"><b class="fl" style="font-size:18px">Seu plano: <span class="grad">'+esc(PLANO.nome)+'</span></b>'+(ASSIN&&ASSIN.valido_ate?'<span class="sm">renova até '+new Date(ASSIN.valido_ate).toLocaleDateString('pt-BR')+'</span>':'')+(pago?'<button class="btn sec sm" data-neg="cancelar" style="color:var(--bad)">Cancelar assinatura</button>':'')+'</div>'+
 usoBar('Concorrentes nesta loja (do plano)',Math.min(conc.length,PLANO.max_concorrentes),PLANO.max_concorrentes)+(vagasExtra()||extrasUsadas()?usoBar('Vagas extras (todas as lojas)',extrasUsadas(),vagasExtra()):'')+usoBar('Lojas',LOJAS.length,PLANO.max_lojas)+usoBar('Usos de IA neste mês',USO_IA,PLANO.ia_mes)+usoBar('Termos monitorados',pl.termos.length,PLANO.max_termos)+'</div>'+
 '<div class="planos">'+PLANOS.map(p=>{const atual=p.id===PLANO.id;return '<div class="card plano'+(p.destaque?' dest':'')+(atual?' atual':'')+'">'+(p.destaque?'<span class="chip ig" style="align-self:flex-start">'+esc(p.destaque)+'</span>':'')+'<b style="font-size:20px">'+esc(p.nome)+'</b><div><b class="preco">R$ '+Number(p.preco).toFixed(0)+'</b><span class="sm">'+(p.preco>0?'/mês':' · para sempre')+'</span></div><ul class="lst">'+
  ['<b>'+p.max_lojas+'</b> loja'+(p.max_lojas>1?'s (clientes)':''),'<b>'+p.max_concorrentes+'</b> concorrentes por loja','Leitura a cada <b>'+p.intervalo_horas+' h</b>','<b>'+p.ia_mes+'</b> usos de IA por mês',p.max_termos?'<b>'+p.max_termos+'</b> tendências (hashtags)':null].filter(Boolean).concat((p.recursos||[]).filter(r=>!['graficos','hashtags','gerador','perfil'].includes(r)).map(r=>esc(NOME_RECURSO[r]||r))).map(x=>'<li>✓ '+x+'</li>').join('')+'</ul>'+
  (atual?'<span class="btn sec" style="pointer-events:none">Plano atual</span>':p.preco>0?'<button class="btn pri" data-assinar="'+p.id+'">Assinar '+esc(p.nome)+'</button>':'<span class="sm">Sempre grátis</span>')+'</div>'}).join('')+'</div>'+
 '<p class="ill" style="margin-top:12px">Pagamento mensal pelo Mercado Pago (cartão de crédito). Cancele quando quiser, sem multa. Ao cancelar, a conta volta para o Grátis e nada é apagado.</p>'+
 (PACOTES.length?'<div class="ph" id="pacotes" style="margin-top:26px"><div><span class="lbl">Vagas extras</span><h2 style="font-size:24px;font-weight:900">Precisa de mais concorrentes?</h2><p class="mut">Some vagas ao seu plano sem trocar de plano. As vagas valem para todas as suas lojas.</p></div></div>'+
 (EXTRAS.length?'<div class="card" style="display:grid;gap:8px;margin-bottom:14px"><b>Seus pacotes</b>'+EXTRAS.map(x=>{const k=PACOTES.find(p=>p.id===x.pacote);return '<div class="row" style="flex-wrap:wrap"><span class="fl">'+esc(k?k.nome:'+'+x.quantidade+' concorrentes')+(x.valido_ate?' <span class="sm">· renova até '+new Date(x.valido_ate).toLocaleDateString('pt-BR')+'</span>':'')+'</span><button class="btn sec sm" data-cancelextra="'+x.id+'" style="color:var(--bad)">Cancelar</button></div>'}).join('')+'</div>':'')+
 '<div class="pacotes">'+PACOTES.map(cardPacote).join('')+'</div><p class="ill" style="margin-top:12px">Ao cancelar um pacote, as concorrentes acima do limite ficam pausadas (nada é apagado). Elas voltam quando você tiver vaga de novo.</p>':'');
 return h}
async function voltaDoPagamento(){const qs=new URLSearchParams(location.search+'&'+(location.hash.split('?')[1]||''));const id=qs.get('preapproval_id');if(!id||!CLOUD)return;
 toast('Confirmando sua assinatura…');const r=await acao('sincronizar_assinatura',{preapproval_id:id});history.replaceState(null,'',location.pathname+'#planos');await carregar();route();toast(r&&r.status==='authorized'?(r.extra?'Vagas extras liberadas! 💜':'Assinatura ativa! Obrigado 💜'):'Pagamento recebido. A ativação pode levar alguns minutos.')}

/* ---------- alertas ---------- */
async function carregaAlertas(){if(!CLOUD)return;try{const r=await sb.from('alertas').select('*').order('criado_em',{ascending:false}).limit(40);ALERTAS=(r&&r.data)||[]}catch(_){ALERTAS=[]}}
function sinoHTML(){const n=ALERTAS.filter(a=>!a.lido).length;return '<button class="btn sec sm sino" data-neg="alertas" aria-label="Alertas'+(n?', '+n+' novos':'')+'">'+ic('mega',16)+(n?'<span class="bolinha">'+(n>9?'9+':n)+'</span>':'')+'</button>'}
function abrirAlertas(){const nomeLoja=id=>{const l=LOJAS.find(x=>x.id===id);return l?l.nome_fantasia:''};
 openModal('<h2 id="mT" style="font-size:21px;font-weight:900">Alertas</h2>'+(temR('alertas')?'<p class="sm">Também enviamos por e-mail para '+esc(conta.resp.email)+'.</p>':'<p class="sm">No plano <b>'+esc(planoCom('alertas'))+'</b> eles também chegam no seu e-mail. <a href="#planos" data-act="close">Ver planos</a></p>')+
 (ALERTAS.length?'<div class="feed" style="max-height:60vh;overflow:auto">'+ALERTAS.map(a=>'<div class="evw"><a class="ev" '+(a.link?'href="'+esc(a.link)+'" target="_blank" rel="noopener"':'')+' style="text-decoration:none;'+(a.lido?'opacity:.7':'')+'"><span class="ib" style="background:'+({viral:'#fa7e1e',promocao:'#4f5bd5',seguidores:'#962fbf',tendencia:'#d62976'}[a.tipo]||'#962fbf')+'">'+ic({viral:'flame',promocao:'tag',seguidores:'users',tendencia:'spark'}[a.tipo]||'mega')+'</span><span class="fl"><b style="font-size:14px">'+esc(a.titulo)+'</b><span class="sm" style="display:block">'+esc(a.texto||'')+'</span><span class="sm">'+quando(a.criado_em)+(LOJAS.length>1?' · '+esc(nomeLoja(a.empresa_id)):'')+'</span></span></a>'+(temR('gerador')&&a.empresa_id===EMP_ID&&/viral|promocao|seguidores|tendencia/.test(a.tipo)?'<button class="btn sec sm" data-rebater="'+a.id+'">⚔️ Criar resposta</button>':'')+'</div>').join('')+'</div>':'<p class="mut">Nenhum alerta ainda. Quando uma concorrente viralizar, lançar promoção ou crescer rápido, aparece aqui.</p>')+'<button class="btn sec" data-act="close">Fechar</button>');
 const nl=ALERTAS.filter(a=>!a.lido).map(a=>a.id);if(nl.length){sb.from('alertas').update({lido:true}).in('id',nl).then(()=>{ALERTAS.forEach(a=>a.lido=true);const b=document.querySelector('.sino .bolinha');if(b)b.remove()})}}

/* ---------- hashtags ---------- */
function hashtagsDe(posts){const m={};(posts||[]).forEach(p=>{const tags=[...new Set((String(p.legenda||'').toLowerCase().match(/#[\p{L}\p{N}_]+/gu)||[]))];const i=(p.curtidas||0)+(p.comentarios||0);tags.forEach(t=>{m[t]=m[t]||{tag:t,n:0,inter:0,vm:0};m[t].n++;m[t].inter+=i;m[t].vm+=(p.vezes_media||0)})});
 return Object.values(m).map(x=>Object.assign(x,{media:Math.round(x.inter/x.n),forca:+(x.vm/x.n).toFixed(1)}))}
function hashChips(posts,max){const H=hashtagsDe(posts).sort((a,b)=>b.n-a.n||b.forca-a.forca).slice(0,max||12);return H.length?'<div class="links">'+H.map(h=>'<span class="chip" title="usada '+h.n+'x · '+h.media+' interações em média">'+esc(h.tag)+' <b style="margin-left:4px;color:#d62976">'+h.n+'x</b></span>').join('')+'</div>':'<p class="sm">Ela quase não usa hashtags nas legendas.</p>'}
function renderHashtagsNicho(){const todos=[];conc.forEach(c=>{const g=IG(c);if(g)g.posts.forEach(p=>todos.push(Object.assign({},p,{_c:c.nome})))});
 const porTag={};todos.forEach(p=>{(String(p.legenda||'').toLowerCase().match(/#[\p{L}\p{N}_]+/gu)||[]).forEach(t=>{(porTag[t]=porTag[t]||new Set()).add(p._c)})});
 const H=hashtagsDe(todos).sort((a,b)=>b.forca*Math.log2(1+b.n)-a.forca*Math.log2(1+a.n)).slice(0,30);const eu=minhaIG();const minhas=eu&&eu.posts?new Set(hashtagsDe(eu.posts).map(x=>x.tag)):new Set();
 if(!H.length)return '<div class="card empty"><h2 style="font-size:20px">Ainda sem hashtags</h2><p class="mut">Quando o Radar ler os posts das concorrentes, o ranking aparece aqui.</p></div>';
 return '<p class="mut" style="margin-bottom:12px">Hashtags usadas pelas concorrentes, ordenadas pela força: quanto os posts com ela engajam em relação à média de cada loja. As marcadas com ✓ você já usa.</p><div class="card" style="overflow-x:auto"><table class="tbl"><thead><tr><th>Hashtag</th><th>Usos</th><th>Lojas</th><th>Força</th><th>Interações</th></tr></thead><tbody>'+H.map(h=>'<tr><td><b>'+esc(h.tag)+'</b>'+(minhas.has(h.tag)?' <span class="chip ok" style="padding:2px 6px">✓</span>':'')+'</td><td>'+h.n+'</td><td>'+(porTag[h.tag]?porTag[h.tag].size:1)+'</td><td><b style="color:'+(h.forca>=1.2?'#16a34a':h.forca<0.8?'#dc2626':'var(--ink)')+'">'+String(h.forca).replace('.',',')+'x</b></td><td>'+fmt(h.media)+'</td></tr>').join('')+'</tbody></table></div><button class="btn sec" style="margin-top:10px" data-copy="'+esc(H.filter(h=>h.forca>=1).slice(0,15).map(h=>h.tag).join(' '))+'">Copiar as 15 mais fortes</button>'}

/* ---------- mapa de calor (dia × horário) ---------- */
function mapaCalor(posts,titulo){const D=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'],F=['0–3h','3–6h','6–9h','9–12h','12–15h','15–18h','18–21h','21–24h'];const g=D.map(()=>F.map(()=>({n:0,s:0})));
 (posts||[]).forEach(p=>{const t=Date.parse(p.data);if(!t)return;const br=new Date(t-3*36e5);const c=g[br.getUTCDay()][Math.floor(br.getUTCHours()/3)];c.n++;c.s+=(p.vezes_media||1)});
 const mx=Math.max(0.01,...g.flat().map(c=>c.n?c.s/c.n:0));let melhor=null;g.forEach((l,i)=>l.forEach((c,j)=>{if(c.n>=2){const v=c.s/c.n;if(v>=1.1&&(!melhor||v>melhor.v))melhor={v,d:D[i],f:F[j]}}}));
 return '<div class="card" style="display:grid;gap:10px"><b>'+esc(titulo)+'</b><div class="heat" role="table" aria-label="Mapa de calor de engajamento"><span></span>'+F.map(f=>'<span class="hh">'+f+'</span>').join('')+g.map((l,i)=>'<span class="hd">'+D[i]+'</span>'+l.map(c=>{const v=c.n?c.s/c.n:0;return '<span class="hc" style="background:'+(c.n?'rgba(214,41,118,'+(0.12+0.88*v/mx).toFixed(2)+')':'var(--soft,#f4f4f7)')+'" title="'+c.n+' posts · '+(c.n?(v).toFixed(1)+'x a média':'sem posts')+'">'+(c.n?c.n:'')+'</span>'}).join('')).join('')+'</div><p class="sm">'+(melhor?'🔥 Melhor janela: <b>'+melhor.d+' '+melhor.f+'</b> ('+melhor.v.toFixed(1).replace('.',',')+'x o engajamento normal). ':'')+'Cor mais forte = posts que engajaram acima da média de cada loja. O número é a quantidade de posts.</p></div>'}

/* ---------- gráficos de evolução ---------- */
let histC={};
async function histConc(id){if(histC[id])return histC[id];const desde=new Date(Date.now()-90*864e5).toISOString();const r=await sb.from('verificacoes').select('feita_em,seg:dados->instagram->seguidores,eng:dados->instagram->engajamento,ps:dados->instagram->posts_semana,meus:dados->minha_loja->seguidores').eq('concorrente_id',id).gte('feita_em',desde).order('feita_em',{ascending:true}).limit(500);
 const L=(r&&r.data)||[];const porDia={};L.forEach(x=>{porDia[x.feita_em.slice(0,10)]=x});histC[id]=Object.values(porDia);return histC[id]}
function graficoBloco(titulo,pts,fmtv,cor){if(pts.length<2)return '<div class="card"><b>'+esc(titulo)+'</b><p class="sm" style="margin-top:6px">O gráfico aparece depois de alguns dias de leituras.</p></div>';const a=pts[0].v,b=pts[pts.length-1].v,d=b-a;
 return '<div class="card"><div class="row" style="flex-wrap:wrap;gap:4px 10px"><b class="fl" style="min-width:160px">'+esc(titulo)+'</b><span class="sm">'+fmtv(b)+' <b style="color:'+(d>=0?'#16a34a':'#dc2626')+'">'+(d>=0?'+':'')+fmtv(d)+'</b> em '+Math.max(1,Math.round((pts[pts.length-1].t-pts[0].t)/864e5))+' dias</span></div>'+linha(pts,640,90,cor)+'</div>'}
function blocoEvolucao(c){const box='evo_'+c.id;histConc(c.id).then(H=>{const el=$(box);if(!el)return;const P=k=>H.filter(x=>typeof x[k]==='number').map(x=>({t:Date.parse(x.feita_em),v:x[k]}));
 el.innerHTML='<div class="two">'+graficoBloco('Seguidores de '+c.nome,P('seg'),fmt,'#d62976')+graficoBloco('Engajamento de '+c.nome,P('eng'),x=>pct(x),'#962fbf')+'</div>'+(P('meus').length>1?graficoBloco('Seus seguidores',P('meus'),fmt,'#4f5bd5'):'');afterRender()});
 return '<div id="'+box+'">'+carregando('Carregando evolução…')+'</div>'}
function formatosBloco(g){const F=(g&&g.ritmo&&g.ritmo.formatos)||[];return F.length?'<div class="card" style="display:grid;gap:10px"><b>Formatos que mais engajam</b>'+barras(F,x=>x.formato+' · '+x.posts+' posts',x=>x.media,'#4f5bd5')+'<p class="sm">Média de interações por post em cada formato.</p></div>':''}

