async function carregaConteudos(){if(!CLOUD)return;const r=await sb.from('conteudos').select('*').eq('empresa_id',EMP_ID).order('criado_em',{ascending:false}).limit(60);CONTEUDOS=(r&&r.data)||[];if(location.hash==='#planejar')route()}
function sugestoesCriar(){const s=[];
 ALERTAS.filter(a=>a.empresa_id===EMP_ID&&/viral|promocao|seguidores/.test(a.tipo)).slice(0,3).forEach(a=>s.push({alerta_id:a.id,titulo:a.titulo,texto:a.texto||''}));
 conc.forEach(c=>{const S=SITE(c);if(S&&S.promocoes&&S.promocoes[0]&&s.length<5)s.push({titulo:c.nome+': '+S.promocoes[0],texto:'Promoção ativa no site da concorrente.'})});
 conc.forEach(c=>{const g=IG(c);if(!g||s.length>=6)return;const top=g.posts.slice(0,12).slice().sort((a,b)=>(b.vezes_media||0)-(a.vezes_media||0))[0];if(top&&top.vezes_media>=2)s.push({titulo:c.nome+': '+top.tipo+' com '+String(top.vezes_media).replace('.',',')+'x a média',texto:(top.legenda||'').slice(0,240)})});
 return s.slice(0,6)}
