function abrirArte(i){const x=(gerado&&gerado.itens&&gerado.itens[i])||{};const prods=((pl.meusProdutos||{}).produtos||[]).filter(p=>p.foto);
 ARTE={titulo:x.capa||x.titulo||'',sub:'',img:null,modelo:'foto',cor:'#d62976'};const p0=$('gProd')&&$('gProd').value!==''?((pl.meusProdutos||{}).produtos||[])[+$('gProd').value]:null;if(p0&&p0.preco)ARTE.sub=reais(p0.preco);
 openModal('<h2 id="mT" style="font-size:21px;font-weight:900">Arte do post</h2><canvas id="cvArte" width="1080" height="1350" style="width:100%;max-width:340px;justify-self:center;border-radius:14px;border:1px solid var(--line)"></canvas>'+
 '<div class="row" style="gap:6px;flex-wrap:wrap">'+[['foto','Foto inteira'],['faixa','Foto + faixa'],['texto','Só texto']].map(m=>'<button class="btn sec sm" data-artem="'+m[0]+'">'+m[1]+'</button>').join('')+'</div>'+
 '<label class="f" for="arT"><span>Título</span><input id="arT" style="padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit" value="'+esc(ARTE.titulo)+'" maxlength="70"></label><label class="f" for="arS"><span>Linha de baixo (preço, chamada, @)</span><input id="arS" style="padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit" value="'+esc(ARTE.sub)+'" maxlength="50" placeholder="Ex.: R$ 59,90 · peça pelo direct"></label>'+
 '<div class="row" style="gap:8px;flex-wrap:wrap">'+(prods.length?'<select id="arP" style="flex:1;min-width:160px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit;background:#fff"><option value="">Foto de um produto…</option>'+prods.slice(0,20).map((p,k)=>'<option value="'+k+'">'+esc(p.nome.slice(0,50))+'</option>').join('')+'</select>':'')+'<label class="btn sec sm" style="cursor:pointer">'+ic('cam',14)+'Enviar foto<input id="arF" type="file" accept="image/*" hidden></label><input id="arC" type="color" value="#d62976" aria-label="Cor" style="width:44px;height:38px;border:1px solid var(--line);border-radius:10px;padding:2px"></div>'+
 '<div class="row"><button class="btn sec fl" data-arteb="baixar">Baixar imagem</button><button class="btn pri fl" data-arteb="compartilhar">Compartilhar</button></div>');
 desenhaArte()}
function quebra(ctx,txt,max){const ws=String(txt||'').split(/\s+/),ls=[];let l='';ws.forEach(w=>{const t=l?l+' '+w:w;if(ctx.measureText(t).width>max&&l){ls.push(l);l=w}else l=t});if(l)ls.push(l);return ls}
function desenhaArte(){const cv=$('cvArte');if(!cv)return;const c=cv.getContext('2d'),W=1080,H=1350,A=ARTE,cor=A.cor||'#d62976';c.clearRect(0,0,W,H);
 const grad=()=>{const g=c.createLinearGradient(0,0,W,H);g.addColorStop(0,'#fa7e1e');g.addColorStop(.45,cor);g.addColorStop(1,'#4f5bd5');return g};
 const cobre=(im,x,y,w,h)=>{const k=Math.max(w/im.width,h/im.height),iw=im.width*k,ih=im.height*k;c.save();c.beginPath();c.rect(x,y,w,h);c.clip();c.drawImage(im,x+(w-iw)/2,y+(h-ih)/2,iw,ih);c.restore()};
 const texto=(y0,cl,tam,maxL)=>{c.fillStyle=cl;c.font='900 '+tam+'px Inter,system-ui,sans-serif';let ls=quebra(c,A.titulo,W-140);if(ls.length>maxL){tam=Math.round(tam*.8);c.font='900 '+tam+'px Inter,system-ui,sans-serif';ls=quebra(c,A.titulo,W-140).slice(0,maxL)}ls.forEach((l,i)=>c.fillText(l,70,y0+i*tam*1.12));return y0+ls.length*tam*1.12};
 const sub=(y,cl)=>{if(!A.sub)return;c.font='700 46px Inter,system-ui,sans-serif';c.fillStyle=cl;c.fillText(A.sub,70,y+20)};
 const marca=(cl)=>{c.font='700 34px Inter,system-ui,sans-serif';c.fillStyle=cl;c.fillText(conta.loja.ig||conta.emp.fantasia,70,H-60)};
 if(A.modelo==='texto'||!A.img){c.fillStyle=grad();c.fillRect(0,0,W,H);const y=texto(H*.38,'#fff',104,5);sub(y+10,'rgba(255,255,255,.92)');marca('rgba(255,255,255,.85)');return}
 if(A.modelo==='foto'){cobre(A.img,0,0,W,H);const g=c.createLinearGradient(0,H*.45,0,H);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(0,0,0,.78)');c.fillStyle=g;c.fillRect(0,H*.45,W,H*.55);
  c.font='900 92px Inter,system-ui,sans-serif';const n=Math.min(3,quebra(c,A.titulo,W-140).length);const y=texto(H-200-n*103-(A.sub?60:0),'#fff',92,3);sub(y,'#fff');c.fillStyle=cor;c.fillRect(70,H-120,140,10);marca('rgba(255,255,255,.9)');return}
 cobre(A.img,0,0,W,H*.62);c.fillStyle=cor;c.fillRect(0,H*.62,W,H*.38);const y=texto(H*.62+120,'#fff',80,3);sub(y,'rgba(255,255,255,.95)');marca('rgba(255,255,255,.85)')}
function arteImagem(src){const im=new Image();im.onload=()=>{ARTE.img=im;if(ARTE.modelo==='texto')ARTE.modelo='foto';desenhaArte()};im.src=src}
async function arteSaida(modo){const cv=$('cvArte');if(!cv)return;let url;try{url=cv.toDataURL('image/png')}catch(e){toast('Não foi possível gerar a imagem com essa foto. Envie a foto do seu aparelho.');return}
 const nome='radar-post-'+Date.now()+'.png';
 if(modo==='compartilhar'&&navigator.canShare){try{const b=await (await fetch(url)).blob();const f=new File([b],nome,{type:'image/png'});if(navigator.canShare({files:[f]})){await navigator.share({files:[f],title:ARTE.titulo});return}}catch(e){if(e&&e.name==='AbortError')return}}
 const a=document.createElement('a');a.href=url;a.download=nome;document.body.appendChild(a);a.click();a.remove();toast('Imagem baixada')}

/* ---------- avaliações do Google ---------- */
function renderAvaliacoes(){if(!temR('avaliacoes'))return trava('avaliacoes','Veja a nota e as avaliações das concorrentes no Google, o que os clientes reclamam delas e responda as suas avaliações com IA.');
 const G=pl.google;let h='<div class="row" style="flex-wrap:wrap;margin-bottom:12px"><p class="mut fl" style="min-width:220px">Nota e avaliações no Google da sua loja e das concorrentes. Atualiza sozinho uma vez por dia.</p><button class="btn pri" data-cr="google" '+(ocupado.google?'disabled':'')+'>'+ic('refresh')+(ocupado.google?'Buscando no Google…':G?'Atualizar agora':'Buscar avaliações')+'</button></div>';
 if(ocupado.google)return h+carregando('Buscando as avaliações no Google…');
 if(!G)return h+'<div class="card empty"><h2 style="font-size:20px">Avaliações do Google</h2><p class="mut">Toque em “Buscar avaliações” para comparar sua nota com as concorrentes.</p></div>';
 if(G.erro)return h+'<div class="note">'+esc(G.erro)+'</div>';
 const lin=(n,g,eu)=>'<tr'+(eu?' class="eu"':'')+'><td><b>'+esc(n)+'</b>'+(g&&g.ok&&g.link?' <a href="'+esc(g.link)+'" target="_blank" rel="noopener" class="sm">mapa ↗</a>':'')+'</td><td>'+(g&&g.ok&&g.nota!=null?'<b>'+String(g.nota).replace('.',',')+'</b> ⭐':'—')+'</td><td>'+(g&&g.ok?fmt(g.avaliacoes||0):'não achada')+'</td></tr>';
 h+='<div class="card"><table class="tbl"><thead><tr><th>Loja</th><th>Nota</th><th>Avaliações</th></tr></thead><tbody>'+lin(conta.emp.fantasia+' (você)',G.eu,1)+(G.conc||[]).map(c=>lin(c.nome,c)).join('')+'</tbody></table><p class="sm">Se alguma loja não foi achada ou veio errada, confira o nome e a cidade cadastrados.</p></div>';
 if(G.resumo&&(G.resumo.reclamacoes||[]).length)h+='<div class="card ai" style="display:grid;gap:10px;margin-top:12px"><span class="chip ig" style="justify-self:start">'+ic('spark')+'O que os clientes reclamam das concorrentes</span><ul class="rot">'+G.resumo.reclamacoes.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ul>'+(G.resumo.oportunidades||[]).map(o=>'<div class="leg"><b>'+esc(o.titulo)+'</b><br><span class="sm">'+esc(o.texto)+'</span></div>').join('')+'<button class="btn sec sm" style="justify-self:start" data-cr="postreclama">⚔️ Criar post sobre isso</button></div>';
 const R=(G.eu&&G.eu.ok&&G.eu.reviews)||[];
 h+='<div class="card" style="display:grid;gap:10px;margin-top:12px"><b style="font-size:18px">Suas avaliações recentes</b>'+(R.length?R.map((v,i)=>'<div class="leg" style="display:grid;gap:6px"><div class="row" style="gap:6px"><b class="fl">'+esc(v.autor||'Cliente')+'</b><span>'+'⭐'.repeat(Math.max(1,Math.min(5,v.nota||0)))+'</span></div><span class="sm" style="color:var(--ink)">'+esc(v.texto||'(sem texto)')+'</span><span class="sm">'+esc(v.quando||'')+'</span>'+(respAval[i]?'<div class="note" style="background:#f0fdf4;border-color:#bbf7d0;color:#14532d">'+esc(respAval[i])+'</div><div class="row" style="gap:6px;flex-wrap:wrap"><button class="btn sec sm" data-copy="'+esc(respAval[i])+'">Copiar resposta</button>'+(G.eu.link?'<a class="btn sec sm" href="'+esc(G.eu.link)+'" target="_blank" rel="noopener">Responder no Google ↗</a>':'')+'</div>':'<button class="btn sec sm" style="justify-self:start" data-resp="'+i+'" '+(ocupado['r'+i]?'disabled':'')+'>'+ic('spark',14)+(ocupado['r'+i]?'Escrevendo…':'Responder com IA')+'</button>')+'</div>').join(''):'<p class="mut">'+(G.eu&&G.eu.ok?'O Google não mostrou avaliações com texto da sua loja.':'Não achamos sua loja no Google. Confira o nome e a cidade em Minha loja.')+'</p>')+'</div>';
 return h}

/* ---------- WhatsApp ---------- */
function blocoWhats(){if(!CLOUD)return '';if(!temR('whatsapp'))return '<div class="card" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div class="fl"><b>Alertas no WhatsApp</b><p class="sm">Receba no WhatsApp quando uma concorrente viralizar ou lançar promoção.</p></div><a class="btn sec sm" href="#planos">Liberar no plano '+esc(planoCom('whatsapp'))+'</a></div>';const P=PERFIL||{};
 return '<div class="card" style="display:grid;gap:10px"><b>Alertas no WhatsApp</b><p class="sm">As novidades das concorrentes chegam também no seu WhatsApp.</p><div class="row" style="gap:8px;flex-wrap:wrap"><input id="waNum" type="tel" inputmode="tel" value="'+esc(P.whatsapp||'')+'" placeholder="(11) 91234-5678" style="flex:1;min-width:180px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit"><label class="row sm" style="gap:6px;color:var(--ink)"><input type="checkbox" id="waOn"'+(P.whatsapp_alertas?' checked':'')+'> Receber</label><button class="btn pri sm" data-neg="salvawa">Salvar</button></div></div>'}

/* ---------- eventos da criação ---------- */
document.addEventListener('submit',e=>{if(e.target&&e.target.id==='fGerar'){e.preventDefault();e.stopImmediatePropagation();gerarAgora((document.querySelector('input[name=gTipo]:checked')||{}).value||'post')}},true);
document.addEventListener('input',e=>{const id=e.target&&e.target.id;if(id==='arT'){ARTE.titulo=e.target.value;desenhaArte()}if(id==='arS'){ARTE.sub=e.target.value;desenhaArte()}if(id==='arC'){ARTE.cor=e.target.value;desenhaArte()}});
document.addEventListener('change',async e=>{const id=e.target&&e.target.id;
 if(id==='arF'){const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>arteImagem(rd.result);rd.readAsDataURL(f)}
 if(id==='arP'&&e.target.value!==''){const p=((pl.meusProdutos||{}).produtos||[]).filter(p=>p.foto)[+e.target.value];if(!p)return;toast('Carregando a foto…');const r=await acao('imagem',{url:p.foto});if(r.dados){arteImagem(r.dados);if(p.preco&&!ARTE.sub){ARTE.sub=reais(p.preco);const s=$('arS');if(s)s.value=ARTE.sub}}else toast(r.erro||'Não foi possível carregar a foto')}});
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('[data-cr],[data-aj],[data-arte],[data-salvar],[data-postei],[data-delcont],[data-sug],[data-artem],[data-arteb],[data-resp],[data-rebater],[data-rebaterc]');if(!t)return;const d=t.dataset;
 if(d.sug!==undefined){const s=sugestoesCriar()[+d.sug];if(s){criarBase=s;route()}return}
 if(d.rebater){const a=ALERTAS.find(x=>x.id===d.rebater);irRebater({alerta_id:d.rebater,titulo:a?a.titulo:'Movimento da concorrente',texto:a?a.texto:''});return}
 if(d.rebaterc){const c=conc.find(x=>x.id===d.rebaterc);if(!c)return;const ia=resumoIA(c,null);irRebater({titulo:'Responder a '+c.nome,texto:[ia.resumo].concat(ia.mudancas||[]).concat((ia.rebater||[]).map(r=>r[0])).filter(Boolean).join(' | ').slice(0,600)});return}
 if(d.artem){ARTE.modelo=d.artem;desenhaArte();return}
 if(d.arteb){arteSaida(d.arteb);return}
 if(d.arte!==undefined){abrirArte(+d.arte);return}
 if(d.salvar!==undefined){salvarConteudo(+d.salvar);return}
 if(d.aj){const i=+d.i,x=gerado.itens[i];ocupado['aj'+i]=d.aj;route();const r=await acao('ajustar',{texto:x.legenda||x.texto,pedido:d.aj});ocupado['aj'+i]=0;if(r.erro)toast(r.erro);else{USO_IA++;if(x.legenda)x.legenda=r.texto;x.texto=r.texto}route();return}
 if(d.postei){const q=await sb.from('conteudos').update({status:'postado',postado_em:new Date().toISOString()}).eq('id',d.postei);if(q.error){toast(traduz(q.error.message));return}const c=CONTEUDOS.find(x=>x.id===d.postei);if(c)c.status='postado';route();toast('Marcado! O Radar mede o resultado nas próximas horas.');return}
 if(d.delcont){confirmModal('Excluir conteúdo?','Ele sai da sua lista. Não apaga nada do Instagram.','Excluir',async()=>{const q=await sb.from('conteudos').delete().eq('id',d.delcont);if(q.error){toast(traduz(q.error.message));return}CONTEUDOS=CONTEUDOS.filter(x=>x.id!==d.delcont);route()});return}
 if(d.resp!==undefined){const i=+d.resp,v=((pl.google||{}).eu||{}).reviews[i];ocupado['r'+i]=1;route();const r=await acao('responder',{avaliacao:v});ocupado['r'+i]=0;if(r.erro)toast(r.erro);else{USO_IA++;respAval[i]=r.texto}route();return}
 const a=d.cr;if(!a)return;
 if(a==='tirabase'){criarBase=null;route();return}
 if(a==='vozed'){ocupado.vozEd=!ocupado.vozEd;route();return}
 if(a==='voz'){ocupado.voz=1;route();const r=await acao('voz');ocupado.voz=0;if(r.erro)toast(r.erro);else{USO_IA++;const E=lojaAtual();E.voz=r;toast('Pronto! A IA aprendeu o jeito da sua marca.')}route();return}
 if(a==='salvavoz'){const E=lojaAtual();const v=Object.assign({},E.voz||{},{regras:$('vozRegras').value.trim()});const q=await sb.from('empresas').update({voz:v}).eq('id',EMP_ID);if(q.error){toast(traduz(q.error.message));return}E.voz=v;ocupado.vozEd=0;route();toast('Regras salvas');return}
 if(a==='produtos'){ocupado.produtos=1;route();const r=await acao('produtos');ocupado.produtos=0;if(r.erro)toast(r.erro);else{pl.meusProdutos=r;toast((r.produtos||[]).length+' produtos lidos do seu site')}route();return}
 if(a==='salvarasc'||a==='salvaag'){gravaConteudo(+d.i,a==='salvaag');return}
 if(a==='aprovconteudos'){aprovConteudos();return}
 if(a==='google'){ocupado.google=1;route();const r=await acao('google');ocupado.google=0;pl.google=r;respAval={};if(!r.erro)USO_IA++;route();return}
 if(a==='postreclama'){const G=pl.google||{};irRebater({titulo:'O que os clientes reclamam das concorrentes',texto:((G.resumo||{}).reclamacoes||[]).join(' | ')});return}});

/* ---------- índice do nicho ---------- */
function blocoIndice(){if(!temR('indice'))return '<div class="card" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div class="fl"><b>Índice do nicho</b><p class="sm">Compare seu engajamento e frequência com a média de '+esc(conta.emp.seg||'seu nicho')+' no Radar.</p></div><a class="btn sec sm" href="#planos">Liberar no plano '+esc(planoCom('indice'))+'</a></div>';
 const I=pl.indice;let h='<div class="card" style="display:grid;gap:10px"><div class="row" style="flex-wrap:wrap"><b class="fl">Índice do nicho · '+esc(conta.emp.seg||'')+'</b><button class="btn sec sm" data-neg="indice" '+(ocupado.indice?'disabled':'')+'>'+ic('refresh',14)+(ocupado.indice?'Calculando…':I?'Atualizar':'Calcular')+'</button></div>';
 if(I&&!I.erro){const lin=(rot,meu,med,f)=>'<tr><td>'+rot+'</td><td><b>'+(meu==null?'—':f(meu))+'</b></td><td>'+(med==null?'—':f(med))+'</td><td>'+(meu==null||med==null?'':meu>=med?'<span style="color:#16a34a;font-weight:800">acima</span>':'<span style="color:#dc2626;font-weight:800">abaixo</span>')+'</td></tr>';
  h+=(I.suficiente?'':'<p class="ill">Ainda há poucas lojas deste nicho no Radar ('+I.perfis+' perfis). O índice fica mais preciso com o tempo.</p>')+'<table class="tbl"><thead><tr><th></th><th>Você</th><th>Mediana do nicho</th><th></th></tr></thead><tbody>'+lin('Engajamento',I.meu&&I.meu.engajamento,I.engajamento,pct)+lin('Posts por semana',I.meu&&I.meu.posts_semana,I.posts_semana,x=>String(x).replace('.',','))+lin('Seguidores',I.meu&&I.meu.seguidores,I.seguidores,fmt)+'</tbody></table><p class="sm">Baseado em '+I.perfis+' perfis do nicho acompanhados no Radar · '+new Date(I.gerado_em).toLocaleDateString('pt-BR')+'</p>'}
 else if(I&&I.erro)h+='<div class="note">'+esc(I.erro)+'</div>';else h+='<p class="sm">Calcule para ver como você está em relação às lojas do seu nicho.</p>';
 return h+'</div>'}

/* ---------- aprovação do cliente ---------- */
let APROV=null;
async function carregaAprov(){const r=await sb.from('aprovacoes').select('*').eq('empresa_id',EMP_ID).order('criado_em',{ascending:false}).limit(5);APROV=(r&&r.data)||[];if(location.hash==='#planejar')route()}
function linkAprov(a){return location.origin+location.pathname.replace(/app\.html$/,'')+'aprovar.html?t='+a.token}
function blocoAprovacao(){if(!temR('aprovacao'))return '<div class="card" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:12px"><div class="fl"><b>Aprovação do cliente</b><p class="sm">Mande o calendário por link e o cliente aprova ou pede ajuste em cada post.</p></div><a class="btn sec sm" href="#planos">Liberar no plano '+esc(planoCom('aprovacao'))+'</a></div>';
 if(APROV===null){carregaAprov();return ''}
 return '<div class="card" style="display:grid;gap:10px;margin-top:12px"><div class="row" style="flex-wrap:wrap"><b class="fl">Aprovação do cliente</b>'+(pl.calendario&&pl.calendario.semana?'<button class="btn pri sm" data-neg="enviaraprov">'+ic('arrow',14)+'Enviar esta semana para aprovação</button>':'')+'</div>'+
 (APROV.length?APROV.map(a=>{const it=a.itens||[];const ap=it.filter(x=>x.status==='aprovado').length,aj=it.filter(x=>x.status==='ajuste').length;return '<div class="leg" style="display:grid;gap:6px"><div class="row" style="flex-wrap:wrap"><b class="fl">'+esc(a.titulo)+'</b><span class="chip ok">'+ap+' aprovados</span>'+(aj?'<span class="chip bad">'+aj+' ajustes</span>':'')+'<span class="chip">'+(it.length-ap-aj)+' pendentes</span></div>'+it.filter(x=>x.status==='ajuste').map(x=>'<span class="sm">✏️ <b>'+esc(x.dia||'')+':</b> '+esc(x.comentario||'')+'</span>').join('')+'<div class="row" style="gap:6px;flex-wrap:wrap"><button class="btn sec sm" data-copy="'+esc(linkAprov(a))+'">Copiar link</button><a class="btn sec sm" target="_blank" rel="noopener" href="https://wa.me/?text='+encodeURIComponent('Olá! Segue o planejamento de posts para aprovação: '+linkAprov(a))+'">Enviar no WhatsApp</a></div></div>'}).join(''):'<p class="sm">Nenhum envio ainda.</p>')+'</div>'}
async function enviarAprov(){const C=pl.calendario;if(!C||!C.semana)return;const hojeTxt=new Date().toLocaleDateString('pt-BR');
 const q=await sb.from('aprovacoes').insert({empresa_id:EMP_ID,titulo:'Semana de '+hojeTxt+' · '+conta.emp.fantasia,itens:C.semana.map(d=>({dia:d.dia,horario:d.horario,formato:d.formato,tema:d.tema,ideia:d.ideia,legenda:d.legenda,status:'pendente'}))}).select().single();
 if(q.error){toast(traduz(q.error.message));return}APROV=[q.data].concat(APROV||[]);route();openModal('<h2 id="mT" style="font-size:21px;font-weight:900">Link de aprovação pronto</h2><p class="mut">Mande para o cliente. Ele não precisa de conta: abre, aprova ou pede ajuste em cada post.</p><div class="leg">'+esc(linkAprov(q.data))+'</div><div class="row"><button class="btn sec fl" data-copy="'+esc(linkAprov(q.data))+'">Copiar link</button><a class="btn pri fl" target="_blank" rel="noopener" href="https://wa.me/?text='+encodeURIComponent('Olá! Segue o planejamento de posts para aprovação: '+linkAprov(q.data))+'">WhatsApp</a></div>')}

/* ---------- marca da agência ---------- */
